from decimal import Decimal

def parse_number(text: str) -> Decimal:
    # Only str accepted
    if not isinstance(text, str):
        raise ValueError("invalid input")
    # 1. strip outer whitespace (space, tab, NBSP only)
    s = text.strip(" \t\u00a0")
    if s == "":
        raise ValueError("empty input")
    is_negative = False
    s_body = None
    # 2/3. parentheses vs sign handling
    if "(" in s or ")" in s:
        # must be exactly outer pair
        if not (len(s) >= 2 and s[0] == "(" and s[-1] == ")"):
            raise ValueError("unbalanced parentheses")
        inner = s[1:-1]
        if "(" in inner or ")" in inner:
            raise ValueError("unbalanced parentheses")
        # leading sign inside parentheses is invalid
        if inner.strip(" \t\u00a0")[:1] in ("+", "-"):
            raise ValueError("sign with parentheses")
        is_negative = True
        s_body = inner
    else:
        # optional single leading sign
        if s[0] in ("+", "-"):
            is_negative = (s[0] == "-")
            s_body = s[1:]
            if s_body == "":
                raise ValueError("sign only")
            if s_body[0] in ("+", "-"):
                raise ValueError("double sign")
        else:
            s_body = s
            is_negative = False
    # 4. remove interior spaces (space and NBSP)
    t = s_body.replace(" ", "").replace("\u00a0", "")
    if t == "":
        raise ValueError("no digits")
    for ch in t:
        if ch not in "0123456789.,":
            raise ValueError("invalid character")
    if not any(ch.isdigit() for ch in t):
        raise ValueError("no digits")
    has_dot = "." in t
    has_comma = "," in t
    num_str = None
    if has_dot and has_comma:
        last_dot = t.rfind(".")
        last_comma = t.rfind(",")
        if last_dot > last_comma:
            dec = "."
            thou = ","
        else:
            dec = ","
            thou = "."
        if t.count(dec) != 1:
            raise ValueError("bad decimal separator")
        idx = t.rfind(dec)
        int_part = t[:idx]
        dec_part = t[idx + 1:]
        if int_part == "" or dec_part == "":
            raise ValueError("empty integer/decimal part")
        if not dec_part.isdigit():
            raise ValueError("bad decimal part")
        # int_part must contain only digits and thou
        for ch in int_part:
            if ch != thou and not ch.isdigit():
                raise ValueError("bad integer part")
        if thou in int_part:
            groups = int_part.split(thou)
            for g in groups:
                if g == "" or not g.isdigit():
                    raise ValueError("bad grouping")
            if not (1 <= len(groups[0]) <= 3):
                raise ValueError("bad grouping")
            for g in groups[1:]:
                if len(g) != 3:
                    raise ValueError("bad grouping")
        else:
            if not int_part.isdigit():
                raise ValueError("bad integer part")
        int_digits = int_part.replace(thou, "")
        if int_digits == "" or not int_digits.isdigit():
            raise ValueError("bad integer part")
        num_str = int_digits + "." + dec_part
    elif has_comma and not has_dot:
        if t.count(",") > 1:
            groups = t.split(",")
            for g in groups:
                if g == "" or not g.isdigit():
                    raise ValueError("bad grouping")
            if not (1 <= len(groups[0]) <= 3):
                raise ValueError("bad grouping")
            for g in groups[1:]:
                if len(g) != 3:
                    raise ValueError("bad grouping")
            num_str = t.replace(",", "")
        else:
            idx = t.find(",")
            int_part = t[:idx]
            dec_part = t[idx + 1:]
            if int_part == "" or dec_part == "":
                raise ValueError("empty integer/decimal part")
            if not int_part.isdigit() or not dec_part.isdigit():
                raise ValueError("bad number")
            num_str = int_part + "." + dec_part
    elif has_dot and not has_comma:
        if t.count(".") > 1:
            groups = t.split(".")
            for g in groups:
                if g == "" or not g.isdigit():
                    raise ValueError("bad grouping")
            if not (1 <= len(groups[0]) <= 3):
                raise ValueError("bad grouping")
            for g in groups[1:]:
                if len(g) != 3:
                    raise ValueError("bad grouping")
            num_str = t.replace(".", "")
        else:
            idx = t.find(".")
            int_part = t[:idx]
            dec_part = t[idx + 1:]
            if int_part == "" or dec_part == "":
                raise ValueError("empty integer/decimal part")
            if not int_part.isdigit() or not dec_part.isdigit():
                raise ValueError("bad number")
            num_str = int_part + "." + dec_part
    else:
        if not t.isdigit():
            raise ValueError("bad integer")
        num_str = t
    if is_negative:
        num_str = "-" + num_str
    try:
        return Decimal(num_str)
    except Exception:
        raise ValueError("invalid number")
